bar.value='\\''39.93'\\'';bar.fire('\\''input'\\'');ctrl.fire('\\''click'\\'');step(1000);
assert(p.state()==='\\''ENDED'\\''&&p.time()===40&&bar.value==='\\''40.000'\\''&&ctrl.attributes['\\''aria-label'\\'']==='\\''Play'\\'','\\''endpoint'\\'');
